// @generated by Claude Code (Sonnet 5.5) on 2026-11-03 — landing page behavior
(() => {
  const $ = (id) => document.getElementById(id);

  // Site root URL (what users paste into the app as "Icon site URL").
  const siteUrl = new URL('.', location.href).href.replace(/\/$/, '');
  $('siteUrl').textContent = siteUrl;

  // Download links: GitHub Releases of the repo that hosts this Pages site (https://owner.github.io/repo/).
  const m = /^([a-z0-9-]+)\.github\.io$/i.exec(location.hostname);
  const repo = location.pathname.split('/').filter(Boolean)[0];
  if (m && repo) {
    const releases = `https://github.com/${m[1]}/${repo}/releases/latest`;
    ['dlWin', 'dlMac'].forEach((id) => {
      const a = $(id);
      a.href = `${releases}/download/${a.dataset.file}`;
    });
    $('allReleases').href = `https://github.com/${m[1]}/${repo}/releases`;
  } else {
    ['dlWin', 'dlMac'].forEach((id) => { $(id).classList.add('disabled'); });
    $('allReleases').removeAttribute('href');
    $('dlNote').textContent = 'Download links activate when this page is published on GitHub Pages and a release exists.';
  }

  $('copySite').addEventListener('click', async (e) => {
    try {
      await navigator.clipboard.writeText(siteUrl);
      e.target.textContent = 'Copied';
    } catch {
      e.target.textContent = 'Copy failed';
    }
    setTimeout(() => { e.target.textContent = 'Copy'; }, 1800);
  });

  const grid = $('iconGrid');
  ICONS.forEach((icon) => {
    const d = document.createElement('div');
    d.className = 'ic';
    d.innerHTML = renderIcon(icon) + '<span></span>';
    d.querySelector('span').textContent = icon.label;
    grid.appendChild(d);
  });
})();
